import type { KeyboardEvent } from 'react';
import { useIntl } from 'react-intl';

import {
  BigNumber,
  ChartHeader,
  DataStateHandler,
  SubPillarCard,
} from 'components';
import { useMediaQuery } from 'hooks';

import {
  StyledHowWeDoItCardRoot,
  StyledHowWeDoItMetricShell,
} from './HowWeDoItCard.styles';
import type { HowWeDoItCardProps } from './types';

const SKELETON_HEIGHT = '140px';

export const HowWeDoItCard = ({
  titleId,
  descriptionId,
  section,
  loading,
  error,
  dataTestId,
  onClick,
}: HowWeDoItCardProps) => {
  const { formatMessage } = useIntl();
  const isDesktopLarge = useMediaQuery('(min-width: 1440px)');
  const isInteractive = Boolean(onClick) && !loading;

  const handleMetricKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!isInteractive || !onClick) {
      return;
    }
    if (
      event.key === 'Enter' ||
      event.key === ' ' ||
      event.key === 'Spacebar'
    ) {
      event.preventDefault();
      onClick();
    }
  };

  return (
    <StyledHowWeDoItCardRoot
      data-testid="new-how-we-do-it-card"
      data-instance-testid={dataTestId}
    >
      <SubPillarCard
        title={formatMessage({ id: titleId })}
        description={formatMessage({ id: descriptionId })}
      >
        <StyledHowWeDoItMetricShell
          data-testid="how-we-do-it-metric-shell"
          interactive={isInteractive}
          onClick={isInteractive ? onClick : undefined}
          onKeyDown={handleMetricKeyDown}
          role={isInteractive ? 'button' : undefined}
          tabIndex={isInteractive ? 0 : undefined}
        >
          <DataStateHandler
            loading={loading}
            error={error}
            empty={!section}
            skeletonProps={{
              height: SKELETON_HEIGHT,
              width: '100%',
              length: 1,
            }}
          >
            <BigNumber
              className="innovation-home-how-we-do-it-big-number"
              header={
                section ? (
                  <ChartHeader
                    title={section.title}
                    period={section.period}
                    measure={section.measure ? section.measure : undefined}
                    config={{ inline: 'horizontal', type: 'small' }}
                    dataTestId={
                      dataTestId ? `${dataTestId}-chart-header` : undefined
                    }
                  />
                ) : null
              }
              data={section?.bigNumberData ?? []}
              asCard={false}
              size={isDesktopLarge ? 'medium' : 'small'}
              spacing="loose"
            />
          </DataStateHandler>
        </StyledHowWeDoItMetricShell>
      </SubPillarCard>
    </StyledHowWeDoItCardRoot>
  );
};
